def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"[A-Z]+[0-9]+|[A-Z]+|[0-9]+|<>|<=|>=|[+\-*/(),:=<>]"
    )
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "~": 3,
        ":": 4,
    }

    def parse_integer(text):
        negative = text.startswith("-")
        if negative:
            text = text[1:]
        value = 0
        for i in range(0, len(text), 9):
            part = text[i:i + 9]
            value = value * (10 ** len(part)) + int(part)
        return -value if negative else value

    def parse(text):
        if not text.startswith("="):
            return ("number", parse_integer(text))

        tokens = token_pattern.findall(text[1:])
        operands = []
        operators = []
        expecting_operand = True
        i = 0

        def reduce_operator():
            op = operators.pop()
            if op == "~":
                operands.append(("unary", operands.pop()))
            else:
                right = operands.pop()
                left = operands.pop()
                if op == ":":
                    operands.append(("range", left[1], right[1]))
                else:
                    operands.append(("binary", op, left, right))

        while i < len(tokens):
            token = tokens[i]

            if token[0].isdigit():
                operands.append(("number", parse_integer(token)))
                expecting_operand = False
            elif token in ("SUM", "MIN", "MAX", "IF"):
                operators.append(["(", token, 0])
                i += 1  # Skip the opening parenthesis.
                expecting_operand = True
            elif token[0].isalpha():
                operands.append(("cell", token))
                expecting_operand = False
            elif token == "(":
                operators.append(["(", None, 0])
                expecting_operand = True
            elif token == ",":
                while isinstance(operators[-1], str):
                    reduce_operator()
                operators[-1][2] += 1
                expecting_operand = True
            elif token == ")":
                while isinstance(operators[-1], str):
                    reduce_operator()
                _, function, commas = operators.pop()
                if function is not None:
                    count = commas + 1
                    args = operands[-count:]
                    del operands[-count:]
                    operands.append(("function", function, args))
                expecting_operand = False
            else:
                op = "~" if token == "-" and expecting_operand else token
                while (
                    operators
                    and isinstance(operators[-1], str)
                    and (
                        precedence[operators[-1]] > precedence[op]
                        or (
                            precedence[operators[-1]] == precedence[op]
                            and op != "~"
                        )
                    )
                ):
                    reduce_operator()
                operators.append(op)
                expecting_operand = True
            i += 1

        while operators:
            reduce_operator()
        return operands[0]

    trees = {name: parse(content) for name, content in cells.items()}
    values = {}
    in_progress = set()

    def function_arguments(args):
        for arg in args:
            if arg[0] != "range":
                yield arg
                continue

            first, second = arg[1], arg[2]
            left = min(ord(first[0]), ord(second[0]))
            right = max(ord(first[0]), ord(second[0]))
            top = min(int(first[1:]), int(second[1:]))
            bottom = max(int(first[1:]), int(second[1:]))

            for row in range(top, bottom + 1):
                for column in range(left, right + 1):
                    name = chr(column) + str(row)
                    if name in trees:
                        yield ("cell", name)

    def evaluate(start):
        tasks = [("cell", start)]
        result = 0

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name in values:
                    result = values[name]
                elif name not in trees:
                    result = 0
                elif name in in_progress:
                    result = "#CYCLE!"
                else:
                    in_progress.add(name)
                    tasks.append(("finish", name))
                    tasks.append(("eval", trees[name]))

            elif kind == "finish":
                name = task[1]
                in_progress.remove(name)
                values[name] = result

            elif kind == "eval":
                node = task[1]
                node_kind = node[0]

                if node_kind == "number":
                    result = node[1]
                elif node_kind == "cell":
                    tasks.append(("cell", node[1]))
                elif node_kind == "unary":
                    tasks.append(("unary",))
                    tasks.append(("eval", node[1]))
                elif node_kind == "binary":
                    tasks.append(("binary_left", node[1], node[3]))
                    tasks.append(("eval", node[2]))
                else:
                    function, args = node[1], node[2]
                    if function == "IF":
                        tasks.append(("if_condition", args[1], args[2]))
                        tasks.append(("eval", args[0]))
                    else:
                        tasks.append(
                            ("function_next", function, iter(function_arguments(args)), None)
                        )

            elif kind == "unary":
                if isinstance(result, int):
                    result = -result

            elif kind == "binary_left":
                if isinstance(result, int):
                    tasks.append(("binary_right", task[1], result))
                    tasks.append(("eval", task[2]))

            elif kind == "binary_right":
                if isinstance(result, int):
                    op, left, right = task[1], task[2], result
                    if op == "+":
                        result = left + right
                    elif op == "-":
                        result = left - right
                    elif op == "*":
                        result = left * right
                    elif op == "/":
                        if right == 0:
                            result = "#DIV/0!"
                        else:
                            quotient = abs(left) // abs(right)
                            result = -quotient if (left < 0) != (right < 0) else quotient
                    elif op == "=":
                        result = int(left == right)
                    elif op == "<>":
                        result = int(left != right)
                    elif op == "<":
                        result = int(left < right)
                    elif op == "<=":
                        result = int(left <= right)
                    elif op == ">":
                        result = int(left > right)
                    else:
                        result = int(left >= right)

            elif kind == "if_condition":
                if isinstance(result, int):
                    tasks.append(("eval", task[1] if result else task[2]))

            elif kind == "function_next":
                function, arguments, accumulator = task[1:]
                try:
                    arg = next(arguments)
                except StopIteration:
                    result = 0 if accumulator is None else accumulator
                else:
                    tasks.append(("function_collect", function, arguments, accumulator))
                    tasks.append(("eval", arg))

            else:  # function_collect
                if isinstance(result, int):
                    function, arguments, accumulator = task[1:]
                    if accumulator is None:
                        accumulator = result
                    elif function == "SUM":
                        accumulator += result
                    elif function == "MIN":
                        accumulator = min(accumulator, result)
                    else:
                        accumulator = max(accumulator, result)
                    tasks.append(("function_next", function, arguments, accumulator))

        return result

    for name in cells:
        if name not in values:
            evaluate(name)

    return {name: values[name] for name in cells}
